SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END order_cohort, SUM(discount) total_discount, ROUND(SUM(discount) * 100.0 / SUM(SUM(discount)) OVER (), 2) AS pct_of_total FROM orders GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY total_discount, order_cohort
